<?php $__env->startSection('content'); ?>
<div class="d-flex flex-wrap justify-content-between gap-3 mb-4"><div class="content-heading"><h1>Order <?php echo e($order->order_number); ?></h1><p>Placed <?php echo e($order->created_at->format('d M Y, h:i A')); ?></p></div><div class="d-flex gap-2"><a href="<?php echo e(route('admin.orders.index')); ?>" class="btn btn-outline-secondary">Back to orders</a><a href="<?php echo e(route('admin.orders.invoice',$order)); ?>" class="btn text-white" style="background:var(--brand)"><i class="bi bi-printer me-1"></i>Invoice</a></div></div>
<div class="row g-4"><div class="col-xl-8"><div class="panel mb-4"><div class="panel-heading mb-3">Order items</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Product</th><th class="text-center">Qty</th><th class="text-end">Price</th><th class="text-end">Total</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $order->items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($item->product_name); ?></td><td class="text-center"><?php echo e(rtrim(rtrim(number_format($item->quantity,2),'0'),'.')); ?></td><td class="text-end">$<?php echo e(number_format($item->unit_price,2)); ?></td><td class="text-end fw-bold">$<?php echo e(number_format($item->line_total,2)); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="4" class="text-center text-muted py-4">Items will be supplied by the storefront.</td></tr><?php endif; ?></tbody><tfoot><tr><td colspan="3" class="text-end">Subtotal</td><td class="text-end">$<?php echo e(number_format($order->subtotal,2)); ?></td></tr><tr><td colspan="3" class="text-end">Shipping</td><td class="text-end">$<?php echo e(number_format($order->shipping_charge,2)); ?></td></tr><tr><th colspan="3" class="text-end">Total</th><th class="text-end fs-5">$<?php echo e(number_format($order->total,2)); ?></th></tr></tfoot></table></div></div><div class="panel"><div class="panel-heading mb-3">Delivery & customer</div><div class="row g-3"><div class="col-md-6"><div class="text-muted small">Customer</div><div class="fw-semibold"><?php echo e($order->customer_name); ?></div><div><?php echo e($order->customer_phone); ?></div><div><?php echo e($order->customer_email); ?></div></div><div class="col-md-6"><div class="text-muted small">Shipping address</div><div><?php echo nl2br(e($order->shipping_address ?: 'Not provided')); ?></div></div><?php if($order->customer_note): ?><div class="col-12"><div class="text-muted small">Customer note</div><div><?php echo e($order->customer_note); ?></div></div><?php endif; ?></div></div></div><div class="col-xl-4"><div class="panel mb-4"><div class="panel-heading mb-3">Change status</div><form method="POST" action="<?php echo e(route('admin.orders.status',$order)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('PUT'); ?><label class="form-label">Current: <span class="order-status <?php echo e($order->status); ?>"><?php echo e(ucfirst($order->status)); ?></span></label><select class="form-select mb-3" name="status" id="order-status"><?php $__currentLoopData = ['pending'=>['accepted','cancelled'],'accepted'=>['processing','cancelled'],'processing'=>['shipped','delivered'],'shipped'=>['delivered']]; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $current=>$next): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?> <?php if($order->status===$current): ?> <?php $__currentLoopData = $next; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $status): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($status); ?>"><?php echo e(ucfirst($status)); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?> <?php endif; ?> <?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><div id="warehouse-assignment" class="mb-3" hidden><label class="form-label">Fulfil from warehouse <span class="text-danger">*</span></label><select class="form-select" name="warehouse_id"><option value="">Select warehouse</option><?php $__currentLoopData = $warehouses; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $warehouse): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($warehouse->id); ?>" <?php if($order->warehouse_id===$warehouse->id): echo 'selected'; endif; ?>><?php echo e($warehouse->name); ?> — <?php echo e($warehouse->code); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><div class="form-text">Stock is reserved from this warehouse when the order starts processing.</div></div><textarea name="note" class="form-control mb-3" rows="2" placeholder="Optional status note"></textarea><button class="btn text-white w-100" style="background:var(--brand)">Update status</button></form></div><div class="panel"><div class="panel-heading mb-3">Order history</div><div class="status-timeline"><?php $__empty_1 = true; $__currentLoopData = $order->statusHistory; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $history): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="timeline-item"><span class="timeline-dot"></span><div><span class="order-status <?php echo e($history->status); ?>"><?php echo e(ucfirst($history->status)); ?></span><div class="small text-muted mt-1"><?php echo e($history->created_at->format('d M Y, h:i A')); ?></div><?php if($history->note): ?><div class="small mt-1"><?php echo e($history->note); ?></div><?php endif; ?></div></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="text-muted small">The timeline begins when order status is updated.</div><?php endif; ?></div></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const status=document.getElementById('order-status'),warehouse=document.getElementById('warehouse-assignment');if(!status||!warehouse)return;const sync=()=>warehouse.hidden=status.value!=='processing';status.addEventListener('change',sync);sync();});</script>
